namespace StageArtPlugIn;
use StageArtPlugIn\Infrastructure\Schema\Schema;use StageArtPlugIn\Infrastructure\Schema\ProductionMigration;use StageArtPlugIn\Infrastructure\Schema\SurveyMigration;use StageArtPlugIn\Infrastructure\Schema\TicketMigration;use StageArtPlugIn\Domain\Production\ProductionValidator;use StageArtPlugIn\Presentation\Admin\AdminMenu;use StageArtPlugIn\Presentation\Admin\MemberAdmin;use StageArtPlugIn\Presentation\Admin\ProductionAdmin;use StageArtPlugIn\Presentation\Admin\SiteSettingsAdmin;use StageArtPlugIn\Presentation\Admin\SurveyAdmin;use StageArtPlugIn\Presentation\Admin\SurveyResultsAdmin;use StageArtPlugIn\Presentation\Admin\SurveyQrAdmin;use StageArtPlugIn\Presentation\Admin\TicketAdmin;use StageArtPlugIn\Presentation\PublicSite\MemberRouter;use StageArtPlugIn\Presentation\PublicSite\MemberShortcodes;use StageArtPlugIn\Presentation\PublicSite\ProductionRouter;use StageArtPlugIn\Presentation\PublicSite\SurveyRouter;use StageArtPlugIn\Presentation\PublicSite\TicketRouter;use StageArtPlugIn\Presentation\Rest\HealthController;use StageArtPlugIn\Presentation\Rest\MemberController;
final class Plugin{public function boot():void{if(get_option('stageart_plugin_db_version')!==Schema::DB_VERSION)Schema::activate();ProductionMigration::ensure();SurveyMigration::ensure();TicketMigration::ensure();add_action('init',static function():void{register_post_type('stageart_production',['labels'=>['name'=>'公演','singular_name'=>'公演'],'public'=>false,'show_ui'=>false,'supports'=>['title'],'rewrite'=>false]);},5);add_action('admin_menu',[new AdminMenu(),'register']);add_action('admin_menu',[new SiteSettingsAdmin(),'register'],20);add_action('admin_menu',[new MemberAdmin(),'register'],20);add_action('admin_menu',[new ProductionAdmin(),'register'],20);add_action('admin_menu',[new SurveyAdmin(),'register'],30);add_action('admin_menu',[new SurveyResultsAdmin(),'register'],31);add_action('admin_menu',[new SurveyQrAdmin(),'register'],32);add_action('admin_menu',[new TicketAdmin(),'register'],33);add_action('admin_post_stageart_save_production',static function():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');(new ProductionValidator())->validate(wp_unslash($_POST));},1);add_action('rest_api_init',static function():void{(new HealthController())->register_routes();(new MemberController())->register_routes();});(new MemberShortcodes())->register();(new MemberRouter())->register();(new ProductionRouter())->register();(new SurveyRouter())->register();(new TicketRouter())->register();}}
